int checks=0,failures=0;
void expect(bool okay,const std::string& text){++checks;if(!okay){++failures;std::cerr<<"FAIL: "<<text<<'\n';}}
template<class F>void rejects(F action,int status,const char* text){bool rejected=false;try{action();}catch(const penta::geometry::Error& e){rejected=e.status==status;}expect(rejected,text);}
penta_mesh_request_v1 primitive(uint32_t operation){penta_mesh_request_v1 r{};r.operation=operation;r.max_work=1000000000;r.parameters[23]=1e-12;return r;}
int embeddedPlane(void*,double u,double v,double* result,uint32_t width,char*,uint64_t){if(width!=5)return 1;result[0]=u;result[1]=v;result[2]=0;result[3]=u;result[4]=v;return 0;}
