    std::vector<double> initial(coarse.mesh.points.size()/3);for(std::size_t n=0;n<initial.size();++n)initial[n]=coarse.mesh.points[3*n];penta_surface_heat_request_v1 heat{};heat.mesh=coarse.mesh.descriptor();heat.width=1;heat.initial=initial.data();heat.t1=.1;heat.time_step=.0001;heat.sample_step=.1;heat.diffusion=1;heat.max_wall_seconds=60;heat.tolerance=1e-12;heat.max_steps=10000;heat.max_work=1000000000;const auto coarseHeat=module.heat(heat);double coarseError=0;for(std::size_t node=0;node<initial.size();++node)coarseError+=std::pow(coarseHeat.values[(coarseHeat.report.samples-1)*initial.size()+node]-std::exp(-.2)*initial[node],2);coarseError=std::sqrt(coarseError/initial.size());std::vector<double> refinedInitial(fine.mesh.points.size()/3);for(std::size_t node=0;node<refinedInitial.size();++node)refinedInitial[node]=fine.mesh.points[3*node];heat.mesh=fine.mesh.descriptor();heat.initial=refinedInitial.data();const auto fineHeat=module.heat(heat);double fineError=0;for(std::size_t node=0;node<refinedInitial.size();++node)fineError+=std::pow(fineHeat.values[(fineHeat.report.samples-1)*refinedInitial.size()+node]-std::exp(-.2)*refinedInitial[node],2);fineError=std::sqrt(fineError/refinedInitial.size());expect(fineError<coarseError*.5,"Consistent-mass sphere l1 heat mode converges under independent mesh refinement.");expect(fineHeat.report.max_energy_increase<1e-10&&fineHeat.report.max_mass_drift[0]<1e-10,"Closed-surface heat energy and mass diagnostics.");std::cout<<"Sphere heat l1 RMS errors "<<coarseError<<" -> "<<fineError<<'\n';
